## Practical Example

Here's a function that sums all elements in an array:

```zeus
function sumArray(arr: i32[], length: i32): i32 {
  let sum: i32 = 0;
  let i: i32 = 0;

  while (i < length) {
    sum = sum + arr.get(i);
    i = i + 1;
  }

  return sum;
}

function main(): i32 {
  let numbers: i32[] = new i32[];
  numbers.push(10);
  numbers.push(20);
  numbers.push(30);
  numbers.push(40);

  return sumArray(numbers, 4);  // Returns 100
}
```

## 2D Array Example

Working with a matrix:

```zeus
class Matrix {
  public data: i32[][];
  public rows: i32;
  public cols: i32;

  constructor(r: i32, c: i32) {
    this.rows = r;
    this.cols = c;
    this.data = new i32[][];

    let i: i32 = 0;
    while (i < r) {
      this.data.push(new i32[c]);
      i = i + 1;
    }
  }

  public setValue(row: i32, col: i32, value: i32): void {
    this.data[row][col] = value;
  }

  public getValue(row: i32, col: i32): i32 {
    return this.data[row][col];
  }
}

function main(): i32 {
  let m: Matrix = new Matrix(3, 3);
  m.setValue(0, 0, 1);
  m.setValue(1, 1, 5);
  m.setValue(2, 2, 9);

  return m.getValue(1, 1);  // Returns 5
}
```

## Bounds Checking

Array access is bounds-checked at runtime. Accessing an invalid index returns a default value:

```zeus
let arr: i32[] = new i32[];
arr.push(10);

let safe: i32 = arr.get(0);    // 10
let oob: i32 = arr.get(100);   // Returns 0 (default for i32)
```

<Aside type="caution">
  Out-of-bounds access returns a default value rather than crashing. Be careful to track array sizes.
</Aside>

